def _create_cancelled_response(self, agent_type: str) -> ChatAgentResponse:
    error_info = SubagentError(
        error_type=SubagentErrorType.CANCELLED,
        message="Subagent execution was cancelled",
        agent_type=agent_type,
        elapsed_seconds=0,
        recoverable=False,
    )
    return ChatAgentResponse(
        response=f"{ERROR_MARKER}\n{error_info.to_supervisor_message()}",
        tool_calls=[],
        citations=[],
    )

async def run(self, ctx: ChatContext) -> ChatAgentResponse:
    with logfire_trace_metadata(
        try:
            multimodal_content = create_multimodal_user_content(ctx)
            message_history = await prepare_multimodal_message_history(
                ctx, self.history_processor
            )
            supervisor_agent = self.create_supervisor_agent(ctx)
            resp = await supervisor_agent.run(
                user_prompt=multimodal_content,
                message_history=message_history,
                metadata=_build_run_metadata(ctx),
            )
            return ChatAgentResponse(
                response=resp.output,
                tool_calls=[],
                citations=[],
            )
        except GenerationCancelled:
            pass

