                                    output_queue, timeout=0.1, max_chunks=50
                                )
                                total_drained_chunks += len(chunks)
                                if completed:
                                    drained_streams.add(tool_call_id)
                                    drain_elapsed = (
                                        asyncio.get_running_loop().time()
                                        - drain_start_time
                                    )
