def run_batch(
    agent_name, agent_version, toolset_version = self._agent_identity()
    if self._context_graph is None:
        return BatchAgentOutcome(
            ok=False,
            error="context_graph_unavailable",
            agent_name=agent_name,
            agent_version=agent_version,
            toolset_version=toolset_version,
        )
    if not ctx.events:
        return BatchAgentOutcome(
            ok=True,
            agent_name=agent_name,
            agent_version=agent_version,
            toolset_version=toolset_version,
        )
    try:
        return asyncio.run(self._run_batch_async(ctx, execution_log=execution_log))
    except Exception as exc:
        return BatchAgentOutcome(
            ok=False,
            error=str(exc),
            agent_name=agent_name,
            agent_version=agent_version,
            toolset_version=toolset_version,
        )

def run_batch(
    if self._context_graph is None:
        pass
    if not ctx.events:
        pass
    try:
        return asyncio.run(self._run_batch_async(ctx, execution_log=execution_log))
    except Exception as exc:
        logger.exception("batch agent run crashed for batch %s", ctx.batch_id)

def run_batch(
    if self._context_graph is None:
        pass
    if not ctx.events:
        pass
    try:
        return asyncio.run(self._run_batch_async(ctx, execution_log=execution_log))
    except Exception as exc:
        pass

async def _run_batch_async(
    exec_log: AgentExecutionLogPort = execution_log or NoOpAgentExecutionLog()
    seq = _SeqAllocator(ctx.start_seq)
    sink = _ExecutionLogSink(exec_log, batch_id=ctx.batch_id, seq=seq)
    state = _BatchRunState(
        pot_id=ctx.pot_id,
        repo_name=ctx.repo_name,
        events_by_id={ev.event_id: ev for ev in ctx.events},
        context_graph=self._context_graph,  # type: ignore[arg-type]
        sink=sink,
    )
    if ctx.resume_completed_event_ids:
        for eid in ctx.resume_completed_event_ids:
            if eid not in state.completed_event_ids:
                state.completed_event_ids.append(eid)
    extra_callables: list[Any] = []
    for builder in self._extra_tool_builders:
        try:
            extra_callables.extend(builder(state) or [])
        except Exception:
            pass

def _cmd_run(args: argparse.Namespace) -> int:
    _configure_logging(args.verbose)
    if getattr(args, "local", False):
        os.environ["POTPIE_BENCH_INPROCESS"] = "1"
    inprocess = os.environ.get("POTPIE_BENCH_INPROCESS", "").strip().lower() in {
        "1",
        "true",
        "yes",
        "on",
    }
    light_only = bool(getattr(args, "light_only", False))
    scenarios = _filter(
        _load_scenarios(),
        use_case=args.use_case,
        scenario_id=args.scenario,
        tier=args.tier,
        difficulty=args.difficulty,
        source_mix=args.source_mix,
        dimension=args.dimension,
        light_only=light_only,
    )
    if not scenarios:
        if light_only:
            pass
        else:
            print(
                f"no scenarios match (use_case={args.use_case!r} tier={args.tier!r} "
                f"difficulty={args.difficulty!r} source_mix={args.source_mix!r} "
                f"dimension={args.dimension!r})",
                file=sys.stderr,
            )
    client = make_client()
    started = now_iso()
    n = len(scenarios)
    n_workers = min(args.concurrency, n) if args.concurrency > 1 and n > 1 else 1
    mode = (
        "in-process (no :8001 server / no worker)"
        if inprocess
        else f"http {client._base}"
    )
    invariant = bool(getattr(args, "invariant", False))
    judge = (
        "off (--skip-judge)"
        if args.skip_judge
        else ("invariant (schema-independent)" if invariant else "rubric")
    )
    label = "benchmark run-light" if light_only else "benchmark run"
    print(
        f"▶ {label} | {n} scenario(s) | mode={mode} | "
        f"concurrency={n_workers}"
        + (
            " (processes)"
            if (n_workers > 1 and inprocess)
            else (" (threads)" if n_workers > 1 else "")
        )
        + f" | tier={('light' if light_only else args.tier)} | judge={judge}"
    )
    results: list = []
    def _run_one(scenario):  # type: ignore[no-untyped-def]
        return run_scenario(
            scenario=scenario,
            client=client,
            fixtures_root=FIXTURES_ROOT,
            benchmarks_root=BENCHMARKS_ROOT,
            ingest_timeout_s=args.ingest_timeout,
            skip_judge=args.skip_judge,
            invariant=invariant,
        )
    if n_workers > 1 and inprocess:
        with ProcessPoolExecutor(max_workers=n_workers) as pool:
            futures = {
                pool.submit(
                    _run_scenario_worker,
                    (s, args.ingest_timeout, args.skip_judge, invariant),
                ): s
                for s in scenarios
            }
            for fut in as_completed(futures):
                s = futures[fut]
                try:
                    result = fut.result()
                except Exception as exc:  # noqa: BLE001 — a crashed subprocess
                    result = _failed_scenario_result(s, f"subprocess crashed: {exc}")
                results.append(result)
    elif n_workers > 1:
        with ThreadPoolExecutor(
            futures = {pool.submit(_run_one, s): s for s in scenarios}
            for fut in as_completed(futures):
                result = fut.result()
                results.append(result)
    else:
        for i, scenario in enumerate(scenarios, 1):
            result = _run_one(scenario)
            results.append(result)
    order = {s.id: i for i, s in enumerate(scenarios)}
    results.sort(key=lambda r: order.get(r.id, 1_000_000))
    finished = now_iso()
    report = aggregate_report(
        schema_version=SCHEMA_VERSION,
        started_at=started,
        finished_at=finished,
        engine_url=client._base,
        tier=args.tier if not args.scenario else "n/a",
        use_case_filter=args.use_case,
        results=results,
    )
    failed = [r for r in results if not r.aggregate_passed]
    if failed:
        for r in failed:
            pass

